    @EventHandler( payloadType=CreateChannelEvent.class )
    public void handle( CreateChannelEvent event) {
	    LOGGER.info("handling CreateChannelEvent - " + event );
	    Channel entity = new Channel();
            entity.setChannelId( event.getChannelId() );
            entity.setName( event.getName() );
            entity.setChannelCode( event.getChannelCode() );
            entity.setLocale( event.getLocale() );
            entity.setDomain( event.getDomain() );
            entity.setAsActive( event.getAsActive() );
            entity.setDefaultCurrency( event.getDefaultCurrency() );
            entity.setChannelType( event.getChannelType() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllChannel( entity );
    }

