    /**
     * Method to retrieve the Channel via an ChannelPrimaryKey.
     * @param 	id Long
     * @return 	Channel
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Channel handle( FindChannelQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getChannelId() );
    }
    
    /**
     * Method to retrieve a collection of all Channels
     *
     * @param	query	FindAllChannelQuery 
     * @return 	List<Channel> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Channel> handle( FindAllChannelQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindChannel,
 * but only if the id matches
 *
 * @param		entity	Channel
 */
	protected void emitFindChannel( Channel entity ) {
		LOGGER.info("handling emitFindChannel" );
		
	    queryUpdateEmitter.emit(FindChannelQuery.class,
	                            query -> query.getFilter().getChannelId().equals(entity.getChannelId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllChannel
	 * 
	 * @param		entity	Channel
	 */
	protected void emitFindAllChannel( Channel entity ) {
		LOGGER.info("handling emitFindAllChannel" );
		
	    queryUpdateEmitter.emit(FindAllChannelQuery.class,
	                            query -> true,
	                            entity);
	}

